const uOf=t=>{if(demo===5){const k=t<.5?t*2:(t-.5)*2,e=.5*k+.5*sm(k);return t<.5?e:1-e}
  if(demo===4||demo===8)return .5-.5*Math.cos(4*Math.PI*t);
  return t<.42?sm(t/.42):t<.52?1:t<.92?1-sm((t-.52)/.4):0};
