  const full=S.log.filter(x=>!x.part).length,ds=[...H.map(x=>x.d),...S.log.map(x=>x.d)],t0=ds.length?Math.min(...ds):Date.now(),wks=Math.max(1,Math.ceil((Date.now()-t0)/6048e5)),exp=Math.min(24,3*wks);
